_M.CLASSES = {}
for index, entry in ipairs(LISTS) do _M.CLASSES[index] = entry[1] end

local NONE = false
local cache = lrucache.new(4096)

local function letter(byte)
    return byte ~= nil and byte >= 97 and byte <= 122
end

local function word(lower, token)
    local from = 1
    while true do
        local first, last = lower:find(token, from, true)
        if not first then return false end
        if not letter(lower:byte(first - 1)) and not letter(lower:byte(last + 1)) then return true end
        from = first + 1
    end
end
_M._word = word

function _M.classify(ua)
    if type(ua) ~= "string" or ua == "" then return nil end
    local cached = cache:get(ua)
    if cached ~= nil then return cached or nil end
    local lower = ua:lower()
    local found = NONE
    for _, entry in ipairs(LISTS) do
        for _, token in ipairs(entry[2]) do
            if word(lower, token) then found = entry[1] break end
        end
        if found then break end
    end
    if #ua <= 512 then cache:set(ua, found) end
    return found or nil
end

return _M
